-- Portal IECLB Parobé
-- Importação do Calendário de Atividades 2026
-- Fonte: calendario2026.pdf
--
-- Tipos utilizados:
--   culto, festa, atividade, reuniao
--
-- Este script é idempotente pelos slugs "calendario-2026-*":
-- se for executado novamente, atualiza os mesmos registros.
--
-- Observação:
-- Uma linha ilegível no calendário de 14/04/2026 não foi convertida.
-- Os demais itens datados legíveis foram incluídos.

SET NAMES utf8mb4;

SET @autor_id = (
    SELECT u.id
    FROM usuarios u
    LEFT JOIN perfis p ON p.id = u.perfil_id
    WHERE u.ativo = 1
    ORDER BY (p.slug = 'administrador') DESC, u.id ASC
    LIMIT 1
);

SET @com_parobe = (
    SELECT id FROM comunidades
    WHERE slug = 'parobe' OR nome = 'Parobé'
    ORDER BY (slug = 'parobe') DESC, id ASC
    LIMIT 1
);

SET @com_entrepelado = (
    SELECT id FROM comunidades
    WHERE slug = 'entrepelado' OR nome = 'Entrepelado'
    ORDER BY (slug = 'entrepelado') DESC, id ASC
    LIMIT 1
);

SET @com_fialho = (
    SELECT id FROM comunidades
    WHERE slug = 'fazenda-fialho' OR nome LIKE '%Fialho%'
    ORDER BY (slug = 'fazenda-fialho') DESC, id ASC
    LIMIT 1
);

SET @com_santa_cruz = (
    SELECT id FROM comunidades
    WHERE slug = 'santa-cruz-do-pinhal' OR nome LIKE 'Santa Cruz%'
    ORDER BY (slug = 'santa-cruz-do-pinhal') DESC, id ASC
    LIMIT 1
);

SET @com_passo_ferreiros = (
    SELECT id FROM comunidades
    WHERE slug = 'passo-dos-ferreiros' OR nome LIKE 'Passo dos Ferreiros%'
    ORDER BY (slug = 'passo-dos-ferreiros') DESC, id ASC
    LIMIT 1
);

START TRANSACTION;

INSERT INTO eventos (
    autor_id,
    comunidade_id,
    categoria_evento_id,
    tipo,
    titulo,
    slug,
    resumo,
    descricao,
    local,
    endereco,
    data_inicio,
    data_fim,
    santa_ceia,
    imagem_capa_id,
    seo_titulo,
    seo_descricao,
    seo_noindex,
    status
)
