-- Conferência
SELECT tipo, COUNT(*) AS total
FROM eventos
WHERE slug LIKE 'calendario-2026-%'
GROUP BY tipo
ORDER BY tipo;

SELECT COUNT(*) AS total_importado
FROM eventos
WHERE slug LIKE 'calendario-2026-%';
